const handleScrollState = () => {
	document.body.classList.toggle(
		'scrolled',
		window.scrollY > 50
	);
};

handleScrollState();

window.addEventListener(
	'scroll',
	handleScrollState,
	{ passive: true }
);

document
  .querySelector('#ShopifyChat')
  ?.shadowRoot
  ?.querySelector('button.chat-toggle')
  ?.click();